/* Define a container and make it a flex container */
div {
  display: flex;
  /* This line activates Flexbox for the div */
  background-color: lightblue;
  padding: 20px;
  border: 1px solid black;
}

/* Add some flex items within the container */
div > p {
  margin: 5px;
  padding: 5px;
  border: 1px dotted gray;
}

/* You can further style the flex items */

/* Flex container with row direction */
div.row {
  display: flex;
  flex-direction: row;
  /* Items arranged horizontally */
  background-color: lightgreen;
}

/* Flex container with column direction */
div.column {
  display: flex;
  flex-direction: column;
  /* Items arranged vertically */
  background-color: lightcoral;
}

/* Styling for flex items */
div > div {
  margin: 10px;
  padding: 10px;
  border: 1px solid black;
}

/* Flex container with wrap behavior */
div.wrap {
  display: flex;
  flex-wrap: wrap;
  /* Items will wrap to the next line if needed */
  background-color: lightyellow;
  width: 300px;
}

/* Styling for flex items */
div > div {
  margin: 5px;
  padding: 5px;
  border: 1px solid black;
  width: 80px;
  height: 50px;
}

/* Flex container with justify-content */
div.justify {
  display: flex;
  justify-content: center;
  /* Items centered along the main axis */
  background-color: lightblue;
  height: 100px;
}

/* Styling for flex items */
div > div {
  margin: 5px;
  padding: 5px;
  border: 1px solid black;
}

/* Flex container with align-items */
div.align {
  display: flex;
  align-items: center;
  /* Items centered along the cross axis */
  background-color: lightgreen;
  height: 100px;
}

/* Styling for flex items */
div > div {
  margin: 5px;
  padding: 5px;
  border: 1px solid black;
}
